import Foundation

// Represents a single flashcard returned by the backend.
struct Flashcard: Codable, Identifiable {
    
    //Creates a local unique identifier so SwiftUI can identify each flashcard
    let id = UUID()
    let front: String
    let back: String
    let explanation: String

    // Defines which properties are encoded and decoded from the backend response.
    // The local UUID is excluded because it is generated by the iOS application
    enum CodingKeys: String, CodingKey {
        case front
        case back
        case explanation
    }
}

// Represents the flashcards data returned for a specific quiz
struct FlashcardResponse: Codable {
    
    // Associates the generated flashcards with their original quiz 
    let quizId: Int
    let flashcards: [Flashcard]
    
}
